CREATE TABLE campaigns(id uuid PRIMARY KEY,farm_id uuid,code text,planting_start date,campaign_end date,created_at timestamptz DEFAULT now());
CREATE TABLE greenhouses(id uuid PRIMARY KEY,farm_id uuid,code text,exploitable_area numeric,total_area numeric);
CREATE TABLE campaign_plantings(campaign_id uuid,greenhouse_id uuid);
CREATE TABLE account_categories(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),code text UNIQUE,label text);
CREATE TABLE payroll_periods(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),code varchar(30) UNIQUE NOT NULL,period_year int,period_month int,period_half text,start_date date,end_date date,pay_date date,status text DEFAULT 'brouillon',validated_at timestamptz,paid_at timestamptz);
CREATE TABLE payslips(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),period_id uuid REFERENCES payroll_periods(id),worker_id uuid REFERENCES workers(id),days_worked numeric(5,2),hours_worked numeric(7,2),hours_overtime numeric(7,2),base_amount numeric(10,2),overtime_amount numeric(10,2),bonuses numeric(10,2),gross_salary numeric(10,2),cnss_employee numeric(10,2),amo_employee numeric(10,2),ir_amount numeric(10,2),other_deductions numeric(10,2),net_salary numeric(10,2),cnss_employer numeric(10,2),amo_employer numeric(10,2),family_allowance_employer numeric(10,2),prof_training_employer numeric(10,2),total_employer_cost numeric(10,2),status text DEFAULT 'brouillon',notes text,paid_at timestamptz,UNIQUE(period_id,worker_id));
CREATE TABLE cost_entries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),payroll_period_id uuid,campaign_id uuid,greenhouse_id uuid,account_category_id uuid,cost_category text,amount numeric,entry_date date,description text,is_planned boolean);
