ALTER TABLE payroll_periods ENABLE ROW LEVEL SECURITY;
ALTER TABLE payslips ENABLE ROW LEVEL SECURITY;
CREATE POLICY old_admin_period ON payroll_periods TO authenticated USING(true) WITH CHECK(true);
CREATE POLICY old_admin_slip ON payslips TO authenticated USING(true) WITH CHECK(true);
GRANT SELECT,INSERT,UPDATE,DELETE ON payroll_periods,payslips TO authenticated;
GRANT SELECT ON campaigns,greenhouses,campaign_plantings,account_categories,cost_entries TO authenticated;
GRANT UPDATE(normal_hourly_rate) ON workers TO authenticated;
CREATE FUNCTION trg_payroll_period_status_change() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF OLD.status IS DISTINCT FROM NEW.status THEN PERFORM sync_payslip_period_to_cost_entries(NEW.id); END IF; RETURN NEW; END $$;
CREATE TRIGGER trg_payroll_period_after_update AFTER UPDATE OF status ON payroll_periods FOR EACH ROW EXECUTE FUNCTION trg_payroll_period_status_change();
CREATE FUNCTION trg_payslip_change() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE pid uuid; state text; BEGIN pid:=coalesce(NEW.period_id,OLD.period_id); SELECT status INTO state FROM payroll_periods WHERE id=pid; IF state IN('valide','paye','cloture') THEN PERFORM sync_payslip_period_to_cost_entries(pid); END IF; RETURN coalesce(NEW,OLD); END $$;
CREATE TRIGGER trg_payslip_after_change AFTER INSERT OR UPDATE OR DELETE ON payslips FOR EACH ROW EXECUTE FUNCTION trg_payslip_change();
